import {pantoneColour,cmykToHex,hexToCmyk,cleanTextColour} from './text-colour.mjs';
export function hsvToHex(h,s,v){
 const f=n=>{const k=(n+h/60)%6;return Math.round(255*(v-v*s*Math.max(0,Math.min(k,4-k,1)))).toString(16).padStart(2,'0');};
 return '#'+f(5)+f(3)+f(1);
}
export function hexToHsv(hex){
 const [r,g,b]=hex.slice(1).match(/../g).map(c=>parseInt(c,16)/255),max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min;
 let h=0;if(d)h=60*(max===r?((g-b)/d+6)%6:max===g?(b-r)/d+2:(r-g)/d+4);
 return [h,max?d/max:0,max];
}
// The browser's native colour popup cannot contain our confirmation button.
export function bindConfirmedColourPicker(input,root,{preview=()=>{}}={}){
 const dialog=document.createElement('section');dialog.className='pf-colour-picker';dialog.setAttribute('aria-label','Vælg tekstfarve');dialog.hidden=true;input.setAttribute('aria-expanded','false');
 dialog.innerHTML='<div class="pf-colour-picker-body"><header><strong>Vælg farve</strong><button type="button" data-cancel aria-label="Annuller farvevalg">×</button></header><div class="pf-colour-field" aria-hidden="true"><i></i></div><label>Farvetone<input data-hue type="range" min="0" max="359" step="1"></label><label class="pf-colour-model">Farvekode<select data-model aria-label="Farvetype"><option value="rgb">RGB</option><option value="cmyk">CMYK (%)</option><option value="pantone">Pantone</option></select></label><div class="pf-colour-rgb" data-panel="rgb"><label>R<input data-channel="0" type="number" min="0" max="255"></label><label>G<input data-channel="1" type="number" min="0" max="255"></label><label>B<input data-channel="2" type="number" min="0" max="255"></label></div><label class="pf-colour-pantone" data-panel="pantone" hidden>Pantone<input data-pantone type="text" placeholder="Fx 717 C" autocomplete="off" spellcheck="false"></label><fieldset class="pf-colour-cmyk" data-panel="cmyk" hidden><legend>CMYK (%)</legend><div><label>C<input data-cmyk="0" type="number" min="0" max="100" step="0.1"></label><label>M<input data-cmyk="1" type="number" min="0" max="100" step="0.1"></label><label>Y<input data-cmyk="2" type="number" min="0" max="100" step="0.1"></label><label>K<input data-cmyk="3" type="number" min="0" max="100" step="0.1"></label></div></fieldset><p class="pf-colour-help">Skærmfarver er vejledende. Endelig trykfarve afklares i korrekturen.</p><p class="pf-colour-error" role="status" aria-live="polite"></p><footer><span class="pf-colour-swatch" aria-label="Valgt farve"></span><button type="button" class="pf-colour-confirm" >Vælg farve</button></footer></div>';
 input.closest('label').after(dialog);const field=dialog.querySelector('.pf-colour-field'),marker=field.querySelector('i'),hue=dialog.querySelector('[data-hue]'),channels=[...dialog.querySelectorAll('[data-channel]')],swatch=dialog.querySelector('.pf-colour-swatch'),pantone=dialog.querySelector('[data-pantone]'),cmyk=[...dialog.querySelectorAll('[data-cmyk]')],error=dialog.querySelector('.pf-colour-error'),confirm=dialog.querySelector('.pf-colour-confirm');let h=0,s=0,v=0,draft=input.value,original=input.value,spec=null,source='rgb',invalid=false;
 const model=dialog.querySelector('[data-model]'),panels=[...dialog.querySelectorAll('[data-panel]')];
 const showModel=value=>{model.value=value;for(const panel of panels)panel.hidden=panel.dataset.panel!==value;};
 const controls=[model,hue,...channels,pantone,...cmyk];controls.forEach(control=>control.disabled=true);
 const validity=message=>{invalid=Boolean(message);error.textContent=message;confirm.disabled=invalid;};
 const paint=()=>{draft=hsvToHex(h,s,v);field.style.backgroundColor=hsvToHex(h,1,1);marker.style.left=`${s*100}%`;marker.style.top=`${(1-v)*100}%`;hue.value=Math.round(h);swatch.style.backgroundColor=draft;channels.forEach((el,i)=>el.value=parseInt(draft.slice(1+i*2,3+i*2),16));if(source!=='pantone')pantone.value='';if(source!=='cmyk')hexToCmyk(draft).forEach((n,i)=>cmyk[i].value=n);preview(draft);};
 const close=(cancel=false)=>{if(cancel)preview(original);dialog.hidden=true;controls.forEach(control=>control.disabled=true);input.setAttribute('aria-expanded','false');input.focus({preventScroll:true});};
 input.addEventListener('click',event=>{event.preventDefault();if(!dialog.hidden){close(true);return;}controls.forEach(control=>control.disabled=false);original=input.value;spec=cleanTextColour(input.colourSpec,input.value);source=spec?.model||'rgb';showModel(source);pantone.value=spec?.model==='pantone'?spec.code:'';if(spec?.model==='cmyk')spec.values.forEach((n,i)=>cmyk[i].value=n);validity('');[h,s,v]=hexToHsv(input.value);paint();dialog.hidden=false;input.setAttribute('aria-expanded','true');});
 model.onchange=()=>{validity('');pantone.value=spec?.model==='pantone'?spec.code:'';(spec?.model==='cmyk'?spec.values:hexToCmyk(draft)).forEach((n,i)=>cmyk[i].value=n);paint();showModel(model.value);};
 hue.oninput=()=>{showModel('rgb');source='rgb';spec=null;validity('');h=Number(hue.value);paint();};
 for(const channel of channels)channel.oninput=()=>{if(channels.some(c=>!c.checkValidity()||c.value==='')){validity('RGB skal være mellem 0 og 255.');return;}source='rgb';spec=null;validity('');[h,s,v]=hexToHsv('#'+channels.map(c=>Number(c.value).toString(16).padStart(2,'0')).join(''));paint();};
 pantone.oninput=()=>{if(!pantone.value.trim()){source='rgb';spec=null;validity('');return;}const colour=pantoneColour(pantone.value);if(!colour){validity('Pantone-koden blev ikke fundet. Brug fx 717 C.');return;}source='pantone';spec=colour;validity('');[h,s,v]=hexToHsv(colour.hex);paint();};
 for(const channel of cmyk)channel.oninput=()=>{const values=cmyk.map(c=>c.value),hex=cmykToHex(values);if(!hex){validity('CMYK skal være mellem 0 og 100 %.');return;}source='cmyk';spec={model:'cmyk',values:values.map(Number),hex};validity('');[h,s,v]=hexToHsv(hex);paint();};
 const move=event=>{showModel('rgb');source='rgb';spec=null;validity('');const r=field.getBoundingClientRect();s=Math.max(0,Math.min(1,(event.clientX-r.left)/r.width));v=1-Math.max(0,Math.min(1,(event.clientY-r.top)/r.height));paint();};
 field.onpointerdown=event=>{if(event.button!==0)return;field.setPointerCapture(event.pointerId);move(event);};field.onpointermove=event=>{if(field.hasPointerCapture(event.pointerId))move(event);};field.onpointerup=event=>{if(field.hasPointerCapture(event.pointerId))field.releasePointerCapture(event.pointerId);};
 dialog.querySelector('[data-cancel]').onclick=()=>close(true);
 dialog.querySelector('.pf-colour-confirm').onclick=event=>{event.preventDefault();if(invalid||channels.some(c=>!c.checkValidity()||c.value===''))return;input.value=draft;input.colourSpec=spec;input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));close();};
 dialog.addEventListener('keydown',event=>{event.stopPropagation();if(event.key==='Escape'){event.preventDefault();close(true);}if(event.key==='Enter'){event.preventDefault();dialog.querySelector('.pf-colour-confirm').click();}});
}
